float f(float x)
{
    return .6 * sin(4. * x + iTime * 3.) * exp(-x * .25);
}



const float zoom = 2.8;  // Zoom-out
float px2uv;             // Pixel to UV conversion factor (defined in main)
float max_thickness;     // Line thickness (defined in main)

float dist_f(vec2 p)
{
    // We have a line between every something pixels.
    // The line vertices lie on f(x).
    int n = int(.5 * iResolution.x);

    // Total horizontal length of the lines (screen length in UV)
    float total_len = iResolution.x * px2uv;

    // Distance between the line vertices (in UV)
    float step_size = total_len / float(n);

    // Index range of the lines which we want to check
    int idx0 = int(floor((p.x - max(max_thickness, step_size)) / step_size));
    int idx1 = int(floor((p.x + max(max_thickness, step_size)) / step_size));

    // Initial distance
    float dist = 1e9;

    // Find the minimum distance from the lines we chose
    for (int i = idx0; i <= idx1; i++)
    {
        // Point A of the line segment
        float ax = float(i) * step_size;
        float ay = f(ax);

        // Point B of the line segment
        float bx = float(i + 1) * step_size;
        float by = f(bx);

        // Distance
        dist = min(dist, sd_segment(p, vec2(ax, ay), vec2(bx, by)));
    }

    return dist;
}

vec3 render(vec2 frag_coord)
{
    // UV
    vec2 uv = px2uv * (frag_coord - iResolution.xy * .5);
    if (iMouse.z > .2)
    {
        uv += px2uv * (abs(iMouse.zw) - iMouse.xy);
    }

    // Cartoon paper effect
    uv += (texture(iChannel0, .4 * uv + vec2(13.4823 * SNAP(iTime, .125), 0.)).xy - .5) * .02;

    // Render grid
    vec3 col = vec3(1., .9, 0.72);
    vec3 col_grid = vec3(0.3, 0.1, 0.065);
    #if 0
    {
        // Snap grid lines to pixels
        // For this to work you need to disable the paper effect above

        #define SNAP_PX(X) SNAP(X, px2uv)

        float d = min(abs(uv.x - SNAP_PX(round(uv.x))), abs(uv.y - SNAP_PX(round(uv.y))));
        if (d < .5 * px2uv) col = mix(col, col_grid, .5);

        vec2 t = uv * 4.;
        d = min(abs(t.x - SNAP_PX(round(t.x))), abs(t.y - SNAP_PX(round(t.y))));
        if (d < .5 * px2uv * 4.) col = mix(col, col_grid, .2);

        d = min(abs(uv.x), abs(uv.y));
        if (d < 1. * px2uv) col = col_grid;
    }
    #else
    {
        // Don't snap to pixels

        float d = min(abs(uv.x - round(uv.x)), abs(uv.y - round(uv.y)));
        if (d < .006) col = mix(col, col_grid, .5);

        vec2 t = uv * 4.;
        d = min(abs(t.x - round(t.x)), abs(t.y - round(t.y)));
        if (d < .006 * 4.) col = mix(col, col_grid, .2);

        d = min(abs(uv.x), abs(uv.y));
        if (d < .012) col = col_grid;
    }
    #endif

    // Distance from f(x)
    float d = dist_f(uv);

    // Render lines
    float thick = max_thickness;
    col = mix(col, vec3(.03, .04, 0.6), smoothstep(thick, thick - px2uv, d));

    return col;
}

void main_image(out vec4 frag_col, in vec2 frag_coord)
{
    // Pixel to UV conversion factor
    px2uv = 2. * zoom / min(iResolution.x, iResolution.y);

    // Line thickness
    max_thickness = .03;

    // Super-sampling
    vec3 col = vec3(0);
    {
        col += render(frag_coord + vec2(-.25, -.25));
        col += render(frag_coord + vec2(-.25, +.25));
        col += render(frag_coord + vec2(+.25, +.25));
        col += render(frag_coord + vec2(+.25, -.25));
    }
    col /= 4.;

    // Output
    col = pow(col, vec3(1. / 2.2));
    frag_col = vec4(col, 1.);
}

